<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeTitleVO;

trait ConsentPurposeTitleAttributeHolder
{
    protected ConsentPurposeTitleVO|string|null $title = null;
    protected bool $titleAssigned = false;

    public function getTitleOrCurrent(ConsentPurposeTitleVO $title): ConsentPurposeTitleVO
    {
        if ($this->titleAssigned) {
            \assert(null !== $this->title);
            return ConsentPurposeTitleVO::from($this->title);
        } else {
            return $title;
        }
    }
    public function titleTryBuildInitial(ConstraintFailList $error): ?ConsentPurposeTitleVO
    {
        return  ConsentPurposeTitleVO::tryFrom($this->titleAssigned ? $this->title : null, $error);
    }
    public function title(ConsentPurposeTitleVO|string $title): static
    {
        $this->title = $title;
        $this->titleAssigned = true;
        return $this;
    }
    public function getTitle(): ?string
    {
        return $this->title instanceof ConsentPurposeTitleVO ? $this->title->value() : $this->title;
    }
    public function isTitleAssigned(): bool
    {
        return $this->titleAssigned;
    }
    public function writeTitleTo(mixed $att): void
    {
        if ($this->titleAssigned) {
            \assert(null !== $this->title);
            $att->title($this->title);
        }
    }
    public function readTitleFrom(mixed $att): void
    {
        if ($att->isTitleAssigned()) {
            $title = $att->getTitle();
            \assert(null !== $title);
            $this->title($title);
        }
    }
    public function unsetTitle(): static
    {
        $this->titleAssigned = false;
        return $this;
    }
    protected function withDefaultTitle(): void
    {
    }
    protected function withAssertedTitleRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->titleAssigned = $this->titleAssigned) {
            $value->title = ConsentPurposeTitleVO::tryFrom($this->title, $errorsList);
        }
    }
}
